import sys

def readints():
	data = list(map(int, sys.stdin.buffer.read().split()))
	it = iter(data)
	return it

it = readints()
try:
	n = next(it); q = next(it)
except StopIteration:
	sys.exit(0)

a = [0] * (n + 1)
for i in range(1, n + 1):
	a[i] = next(it)

# 树状数组（1-indexed）
bit_sum = [0] * (n + 2)
bit_sq  = [0] * (n + 2)

def add(bit, idx, delta):
	while idx <= n:
		bit[idx] += delta
		idx += idx & -idx

def sum_prefix(bit, idx):
	res = 0
	while idx > 0:
		res += bit[idx]
		idx -= idx & -idx
	return res

def sum_range(bit, l, r):
	return sum_prefix(bit, r) - sum_prefix(bit, l - 1)

for i in range(1, n + 1):
	add(bit_sum, i, a[i])
	add(bit_sq,  i, a[i] * a[i])

out = []
for _ in range(q):
	t = next(it)
	if t == 1:
		i = next(it); x = next(it)
		delta = x - a[i]
		delta_sq = x * x - a[i] * a[i]
		add(bit_sum, i, delta)
		add(bit_sq,  i, delta_sq)
		a[i] = x
	else:
		l = next(it); r = next(it)
		S = sum_range(bit_sum, l, r)
		Q = sum_range(bit_sq,  l, r)
		m = r - l + 1
		mean = S / m
		var = Q / m - mean * mean
		if var < 0 and var > -1e-12:
			var = 0.0
		out.append(f"{var:.6f}\n")

sys.stdout.write(''.join(out))
